function startAfterStory(){S.bossAfter=false;S.storyScenes=null;S.beforeBoss=null;S.storyIndex=0;$('battle').hidden=true;$('titleScreen').hidden=true;$('lobby').hidden=true;$('storyView').hidden=false;document.body.classList.remove('battle-mode','lobby-mode');document.body.classList.add('story-mode');renderAfterStory();}
function startBossStory(options){S.bossAfter=false;stopOpening();S.token++;S.storyScenes=EnochBossStory.scenes;S.beforeBoss=options;S.storyIndex=0;$('titleScreen').hidden=true;$('lobby').hidden=true;$('battle').hidden=true;$('storyView').hidden=false;document.body.classList.remove('battle-mode','lobby-mode');document.body.classList.add('story-mode');renderAfterStory();}
function startBossAfterStory(){S.storyScenes=EnochBossStory.afterScenes;S.beforeBoss=null;S.bossAfter=true;S.storyIndex=0;$('battle').hidden=true;$('storyView').hidden=false;document.body.classList.remove('battle-mode','lobby-mode');document.body.classList.add('story-mode');renderAfterStory();}
function storyScenes(){return S.storyScenes||EnochAfterStory.scenes;}
function renderAfterStory(){const scene=storyScenes()[S.storyIndex];$('storyTitle').textContent=scene.title;$('storyText').textContent=scene.text;$('storyView').classList.toggle('warning-scene',!!scene.warning);$('storyNext').textContent='次へ';document.querySelector('.story-copy').scrollTop=0;$('storyText').scrollTop=0;$('storyArt').style.backgroundImage=`url('${scene.art}')`;$('storyArt').classList.toggle('departing',!!scene.depart);$('storyArt').classList.toggle('human-story',!!scene.human);$('storyNext').textContent=S.storyIndex===storyScenes().length-1?(S.secretIntro?'一発勝負へ':S.secretVictory?'タイトルへ':S.beforeBoss?'ボス戦へ':S.bossAfter?(playerStore.profile.secret?.pending?'次へ':'タイトルへ'):'CP1へ'):'次へ';$('storyNext').disabled=automatic();if(automatic()){const token=S.token,index=S.storyIndex;setTimeout(()=>{if(token===S.token&&S.storyIndex===index&&!$('storyView').hidden)$('storyNext').onclick();},2400);}}
$('storyNext').onclick=()=>{if(S.storyIndex<storyScenes().length-1){S.storyIndex++;renderAfterStory();return;}if(S.secretIntro){S.secretIntro=false;begin({secret:true,enemyId:'catalnid',skipOpening:true});return;}if(S.secretVictory){S.secretVictory=false;S.storyScenes=null;showTitle();return;}if(S.bossAfter){S.bossAfter=false;S.storyScenes=null;playerStore.profile.story={...playerStore.profile.story,cp1BossExplained:true};playerStore.save();if(playerStore.profile.secret?.pending)startSecretStory();else showTitle();return;}if(S.beforeBoss){const options=S.beforeBoss;S.beforeBoss=null;S.storyScenes=null;begin({...options,bossStorySeen:true});return;}const profile=playerStore.profile;profile.story={...profile.story,firstBattleExplained:true,ctScanReadable:true};if(!profile.history.some(e=>e.type==='story-complete'))profile.history.push({type:'story-complete',at:new Date().toISOString()});profileSaved=playerStore.save();renderProfile();$('storyView').hidden=true;document.body.classList.remove('story-mode');showLobby('campaign');if(automatic()){const token=S.token;setTimeout(()=>{if(token===S.token&&!$('lobby').hidden)begin();},3000);}};
let opRunner=null;
function stopOpMusic(){}
function startOpMusic(){}
function stopOpening(){if(opRunner)opRunner.cancel();opRunner=null;stopOpMusic();}
function startOpening(){if(!nameGate(startOpening))return;if(playerStore.profile.stageLock){showStageLock();return;}if(worldExited())return;stopOpening();exit();if(worldExited()){showTitle();return;}S.encounter=0;const enemyId='lilith';S.storyEnemy=enemyId;$('titleScreen').hidden=true;$('lobby').hidden=true;$('battle').hidden=true;$('opView').hidden=false;document.body.classList.remove('battle-mode','lobby-mode');document.body.classList.add('op-mode');$('opText').textContent='';$('opLyrics').replaceChildren();const finish=()=>{stopOpMusic();$('opView').hidden=true;document.body.classList.remove('op-mode');begin({story:true,skipOpening:true,enemyId});};opRunner=EnochOpening.createRunner({manual:true,wait:pause,enterBattle:finish,show:cue=>{const view=$('opView');view.className='op-view scene-'+cue.scene+(cue.transition?' transitioning':'')+(cue.singing?' singing':'')+(cue.destruction?' destruction':'')+(cue.running?' running':'')+(cue.encounter?' encounter':'')+(cue.declaration?' declaring':'')+(cue.image?' guide-scene':'');$('opGuide').hidden=!cue.image;if(cue.image){$('opGuideImage').src=cue.image;$('guideScroll').classList.remove('zoomed');$('zoomGuide').setAttribute('aria-pressed','false');$('zoomGuide').textContent='図を拡大';$('guideScroll').scrollTop=0;}$('opText').textContent=cue.text;$('opLyrics').replaceChildren(...(cue.lyrics||[]).map((line,i)=>el('p',i===cue.active?'active':'',line)));if(cue.singing)startOpMusic();else stopOpMusic();if(cue.declaration)tone('SKILL');}});opRunner.start();}
$('cancelCommitment').onclick=()=>$('commitmentDialog').close();$('confirmCommitment').onclick=()=>{$('commitmentDialog').close();begin(S.pendingBegin);};
$('startOpening').onclick=startOpening;$('skipOpening').onclick=()=>{if(opRunner)opRunner.skip();};
$('enterLobby').onclick=showLobby;$('lobbyTitle').onclick=showTitle;$('infoBtn').onclick=()=>openInfo();$('hintBtn').onclick=()=>openInfo(true);$('closeInfo').onclick=()=>$('infoDialog').close();$('start').onclick=()=>begin(S.collectionMode==='campaign'?{campaign:true,enemyId:playerStore.cp1Next()||'producer'}:{});$('back').onclick=showTitle;$('home').onclick=e=>{e.preventDefault();showTitle()};$('sound').onclick=()=>{S.sound=music.setEnabled(!S.sound);$('sound').textContent=S.sound?'音 ON':'音 OFF';$('sound').setAttribute('aria-pressed',String(S.sound));if(S.sound)tone('SKILL')};lobby();renderAccess();

// Resolve game buttons at the document boundary, so title/back/dialog controls are included.
let dispatchingChoice=false;
function selectableButtons(){return [...document.querySelectorAll('button,a[href],input[type=checkbox],input[type=radio],input[type=button],input[type=submit],summary,[role=button]')].filter(node=>!node.disabled&&node.getAttribute('aria-disabled')!=='true'&&!node.closest('[inert]')&&node.getClientRects().length>0&&getComputedStyle(node).visibility!=='hidden'&&(!document.querySelector('dialog[open]')||node.closest('dialog[open]')));}
function dispatchOtherChoice(selected){const options=selectableButtons(),chosen=EnochAleph.choose(playerStore.profile,selected,options);if(!chosen)return false;const label=node=>node.getAttribute('aria-label')||node.textContent?.trim()||node.id||'ボタン';$('choiceOutcome').textContent='選択：'+label(selected)+' → 実行：'+label(chosen);const game=S.game,previous=game?.forcedActionSide;if(game)game.forcedActionSide=0;dispatchingChoice=true;try{chosen.click();}finally{dispatchingChoice=false;if(game){if(previous===undefined)delete game.forcedActionSide;else game.forcedActionSide=previous;}}return true;}
document.addEventListener('click',event=>{if(dispatchingChoice||!misdirected()||worldExited())return;const selected=event.target.closest?.('button,a[href],input[type=checkbox],input[type=radio],input[type=button],input[type=submit],summary,[role=button]');if(!selected||!selectableButtons().includes(selected))return;event.preventDefault();event.stopImmediatePropagation();dispatchOtherChoice(selected);},true);

function showStageLock(){const lock=playerStore.profile.stageLock;if(!lock)return;stopOpening();S.token++;S.busy=false;for(const id of ['titleScreen','lobby','opView','storyView'])$(id).hidden=true;$('battle').hidden=false;document.body.classList.remove('lobby-mode','op-mode','story-mode');document.body.classList.add('battle-mode');const r=$('result');r.hidden=false;r.replaceChildren(el('h2','',lock.result.resolutionPending?'勝者裁定未確定・ステージ継続':'勝敗確定・ステージ継続'),el('p','',lock.source),el('p','',lock.result.resolutionPending?'勝者の裁定は未確定です。':lock.result.winner===0?'対局結果：あなたの勝利。':'対局結果：あなたの敗北。'),el('p','','ℵスキルの影響が3つ以上あるため、このステージは終了しません。次の対局へは進みません。'));r.append(el('p','micro','影響：'+lock.influences.map(s=>s.join(' ／ ')).filter(Boolean).join(' ｜ ')),button('効果・ログ',()=>openInfo(),'',!S.game),button('タイトルへ',showTitle));$('phase').textContent='STAGE CONTINUES';for(const id of ['actions','skillActions','keys','ops'])$(id).replaceChildren();}
if(playerStore.profile.stageLock)showStageLock();

function renderWorld(){const gone=worldStore.world.humanCharactersGone,rate=Math.max(0,Math.min(100,Number(worldStore.world.destructionRate)||0));document.body.classList.toggle('humans-gone',gone);$('worldStatus').hidden=!gone&&rate===0;$('worldStatus').textContent=gone?'♩ファイナルライブ：この世界の人間キャラクターは消滅しています。':`WORLD DESTRUCTION ${rate}% — 非DEG17のストーリー敗北で5%上昇。100%で世界破壊。`;}
function renderCP1(){const next=playerStore.cp1Next(),done=playerStore.profile.cp1?.complete;$('cp1Status').textContent=done?'CP1 CLEAR':next?'CP1 — 次の対戦へ':'CP1';$('continueCP1').textContent=done?'CP1の結果':'CP1を進める';}
function continueCP1(){if(playerStore.profile.secret?.pending){startSecretStory();return;}if(!nameGate(continueCP1))return;if(playerStore.profile.stageLock){showStageLock();return;}if(!playerStore.profile.story?.firstBattleExplained){startOpening();return;}const next=playerStore.cp1Next();if(!next){showLobby();$('cp1Status').textContent='CP1 CLEAR — '+(worldStore.world.humanCharactersGone?'人間キャラクター消滅':'攻略完了');return;}if(S.collectionMode!=='campaign'){showLobby('campaign');return;}begin({campaign:true,enemyId:next});}
$('continueCP1').onclick=continueCP1;$('lobbyCP1').onclick=()=>showLobby('campaign');$('confirmProducer').onclick=()=>$('producerDialog').close();$('leaveProducer').onclick=()=>{$('producerDialog').close();showTitle();};renderCP1();

function openRecycle(){if(!S.game)return;$('recycleChoices').replaceChildren(...E.recycleTargets(S.game).map(source=>button(source.label+'：'+source.sym,()=>{S.copyKey=source.key;$('recycleDialog').close();render();})));if(!$('recycleChoices').children.length)$('recycleChoices').append(el('p','','使用済み演算子はありません。'));$('recycleDialog').showModal();}
$('closeRecycle').onclick=()=>$('recycleDialog').close();

// Scene selection never reads hidden card effects or changes game state.
const music=EnochMusic.create();
$('musicVolume').oninput=()=>music.setVolume(Number($('musicVolume').value)/100);
function syncMusic(){let scene='title',part=0,dense=false;
 if(!$('opView').hidden){const v=$('opView');scene=v.classList.contains('scene-1')?'shop':v.classList.contains('scene-2')?'live':'battle';dense=v.classList.contains('destruction');}
 else if(!$('storyView').hidden)scene='story';
 else if(!$('battle').hidden){const g=S.game,chain=g?.p.find(p=>p.producerChain)?.producerChain;scene=g?.cpBossOwner===1&&!g?.result?'boss':g?.finalLive?'finale':g?.result?'result':chain?'live':'battle';part=chain?.index||0;dense=!!chain;}
 else if(!$('lobby').hidden)scene='shop';
 music.setScene(scene,{part,dense});const label='BGM：'+music.state.name+(scene==='boss'?'（原曲）':'（テストBGM）');if($('musicVolume').title!==label)$('musicVolume').title=label;
}
const musicObserver=new MutationObserver(syncMusic);musicObserver.observe(document.body,{subtree:true,attributes:true,attributeFilter:['hidden','class']});
document.addEventListener('visibilitychange',()=>{music.setHidden(document.hidden);if(document.hidden&&S.audio)S.audio.suspend();else if(S.sound&&S.audio)S.audio.resume();});
window.addEventListener('pagehide',()=>music.stop());
window.addEventListener('pageshow',()=>{syncMusic();music.setHidden(document.hidden);});syncMusic();

